use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl SelfProfiler { pub fn new (output_directory : & Path , crate_name : Option < & str > , event_filters : Option < & [String] > , counter_name : & str ,) -> Result < SelfProfiler , Box < dyn Error + Send + Sync > > { fs :: create_dir_all (output_directory) ? ; let crate_name = crate_name . unwrap_or ("unknown-crate") ; let pid : u32 = process :: id () ; let filename = format ! ("{crate_name}-{pid:07}.rustc_profile") ; let path = output_directory . join (filename) ; let profiler = Profiler :: with_counter (& path , measureme :: counters :: Counter :: by_name (counter_name) ?) ? ; let query_event_kind = profiler . alloc_string ("Query") ; let generic_activity_event_kind = profiler . alloc_string ("GenericActivity") ; let incremental_load_result_event_kind = profiler . alloc_string ("IncrementalLoadResult") ; let incremental_result_hashing_event_kind = profiler . alloc_string ("IncrementalResultHashing") ; let query_blocked_event_kind = profiler . alloc_string ("QueryBlocked") ; let query_cache_hit_event_kind = profiler . alloc_string ("QueryCacheHit") ; let artifact_size_event_kind = profiler . alloc_string ("ArtifactSize") ; let query_cache_hit_count_event_kind = profiler . alloc_string ("QueryCacheHitCount") ; let mut event_filter_mask = EventFilter :: empty () ; if let Some (event_filters) = event_filters { let mut unknown_events = vec ! [] ; for item in event_filters { if let Some (& (_ , mask)) = EVENT_FILTERS_BY_NAME . iter () . find (| & (name , _) | name == item) { event_filter_mask |= mask ; } else { unknown_events . push (item . clone ()) ; } } if ! unknown_events . is_empty () { unknown_events . sort () ; unknown_events . dedup () ; warn ! ("Unknown self-profiler events specified: {}. Available options are: {}." , unknown_events . join (", ") , EVENT_FILTERS_BY_NAME . iter () . map (|& (name , _) | name . to_string ()) . collect ::< Vec < _ >> () . join (", ")) ; } } else { event_filter_mask = EventFilter :: DEFAULT ; } Ok (SelfProfiler { profiler , event_filter_mask , string_cache : RwLock :: new (FxHashMap :: default ()) , query_event_kind , generic_activity_event_kind , incremental_load_result_event_kind , incremental_result_hashing_event_kind , query_blocked_event_kind , query_cache_hit_event_kind , artifact_size_event_kind , query_cache_hit_count_event_kind , query_hits : Default :: default () , }) } # [doc = " Allocates a new string in the profiling data. Does not do any caching"] # [doc = " or deduplication."] pub fn alloc_string < STR : SerializableString + ? Sized > (& self , s : & STR) -> StringId { self . profiler . alloc_string (s) } # [doc = " Store a cache hit of a query invocation"] pub fn increment_query_cache_hit_counters (& self , id : QueryInvocationId) { let mut guard = self . query_hits . upgradable_read () ; let query_hits = & guard ; let index = id . 0 as usize ; if index < query_hits . len () { query_hits [index] . fetch_add (1 , Ordering :: Relaxed) ; } else { guard . with_upgraded (| vec | { vec . resize_with (index + 1 , | | AtomicU64 :: new (0)) ; vec [index] = AtomicU64 :: from (1) ; }) ; } } # [doc = " Gets a `StringId` for the given string. This method makes sure that"] # [doc = " any strings going through it will only be allocated once in the"] # [doc = " profiling data."] pub fn get_or_alloc_cached_string < A > (& self , s : A) -> StringId where A : Borrow < str > + Into < String > , { { let string_cache = self . string_cache . read () ; if let Some (& id) = string_cache . get (s . borrow ()) { return id ; } } let mut string_cache = self . string_cache . write () ; match string_cache . entry (s . into ()) { Entry :: Occupied (e) => * e . get () , Entry :: Vacant (e) => { let string_id = self . profiler . alloc_string (& e . key () [..]) ; * e . insert (string_id) } } } pub fn map_query_invocation_id_to_string (& self , from : QueryInvocationId , to : StringId) { let from = StringId :: new_virtual (from . 0) ; self . profiler . map_virtual_to_concrete_string (from , to) ; } pub fn bulk_map_query_invocation_id_to_single_string < I > (& self , from : I , to : StringId) where I : Iterator < Item = QueryInvocationId > + ExactSizeIterator , { let from = from . map (| qid | StringId :: new_virtual (qid . 0)) ; self . profiler . bulk_map_virtual_to_single_concrete_string (from , to) ; } pub fn query_key_recording_enabled (& self) -> bool { self . event_filter_mask . contains (EventFilter :: QUERY_KEYS) } pub fn event_id_builder (& self) -> EventIdBuilder < '_ > { EventIdBuilder :: new (& self . profiler) } }
}